-- S96 (Module 14): MSK pain programmes (back, neck, knee, hip) on the S63 therapy-programme engine.
-- NOT APPLIED TO PRODUCTION. Everything seeded is a DRAFT and nothing is signed, approved, confirmed, attested or switched on: the guard
-- `therapy_pain_enabled` stays OFF, every programme version stays 'draft', every exclusion list stays 'draft'. The Chief Medical Officer signs
-- (approve_therapy_programme_version, save/confirm_therapy_exclusion_list, and the two attestations); a physiotherapist reviewer can be added
-- later with no rebuild because the content is versioned rows and the approval is one function. This migration adds no physiotherapist role.
--
-- VERSION NOTE. The stamp below was read from the clock (20261027184235); live `list_migrations` on koiplnmbgnqnbywhpjlf was read first and
-- its newest version is 20261026192347, the same as origin/main-dev, so this sorts after both.
--
-- WHAT THIS DOES
--   1. therapy_programme_sessions.exercises (jsonb): the structured exercises of a session (name, plain steps, dose, easier and harder version,
--      stop-if rule, drawing key and alt text). Frozen with the rest of an approved version.
--   2. therapy_enrolments.stop_reason gains 'flare_up_review' (a flare-up that failed the re-check pauses the plan for a clinician).
--      public.resume_therapy_enrolment is patched by exact-match anchor (fails loudly) to resume that pause too.
--   3. therapy_msk_events (new, patient-keyed, own-read only, registered in the S39d data registry): difficulty ratings, flare-up reports,
--      step-down periods. Written only by the functions below.
--   4. public.start_msk_session: asks the S48a activity safety gate first (rest => no session opens; restrict => gentle exercises only), then
--      calls start_therapy_session UNCHANGED (so the entry screen is re-run every session and fails closed), then adds the exercises.
--      public.record_msk_exercise_rating: difficulty 1 to 5 after an exercise. public.complete_msk_session: a week finishes only after enough
--      different days have a rating (the completion gate), then calls complete_therapy_session UNCHANGED (checkpoint scores, worsening check).
--      public.report_msk_flare_up: "my pain got worse". It RE-RUNS the deterministic red-flag screen (fails closed). A positive pauses the plan
--      (hard stop for the crisis route), raises a clinical_tasks row through the S63 routing, and tells the patient what to do. A clear
--      re-check records a step-down for a few days. No language model anywhere (INV-01).
--   5. Entry lists: exclusion list version 2 for pain_back, pain_neck, pain_knee, pain_hip (DRAFT, 17, 19, 16 and 16 items). Version 1
--      stays as history. The newest version is the one in force, and `exclusion_list_confirmed` needs the NEWEST version confirmed, so the CMO
--      must confirm version 2 before the guard can be switched on.
--   6. therapy_programme_config version 2 (active): version 1 with the pain instruments replaced by the free PEG (3 items) plus one
--      function goal, their ranges and worsening thresholds, and an `msk` settings block. Every other programme reads identical values. PROPOSED.
--   7. Content: 4 programmes x 8 weekly sessions of DRAFT text with 3 exercises a day at most. The four pain programmes move from 'scaffold'
--      to 'draft'. Nothing patient-visible changes while the guard is off.
--
-- ROWS AFFECTED. 4 therapy_programmes rows updated (status, title, summary); inserted: 32 session rows, 4 exclusion-list versions with 68 rules,
-- 1 config row (the previous config row is set inactive). 0 enrolments are expected on any pain programme (the guard has been off since S63, and
-- a screen stop writes a 'blocked' row at most), so no data conversion is needed.

-- ---------------------------------------------------------------------------
-- 1. Structured exercises on a session
-- ---------------------------------------------------------------------------
alter table public.therapy_programme_sessions
  add column if not exists exercises jsonb;
alter table public.therapy_programme_sessions
  drop constraint if exists therapy_programme_sessions_exercises_shape;
alter table public.therapy_programme_sessions
  add constraint therapy_programme_sessions_exercises_shape
  check (exercises is null or (jsonb_typeof(exercises) = 'array' and jsonb_array_length(exercises) >= 1));
comment on column public.therapy_programme_sessions.exercises is 'S96: the exercises of a pain-programme session (key, name, intensity, steps, dose, easier, harder, stop_if, alt). Frozen with an approved version (the sessions immutability trigger). The daily cap is in therapy_programme_config.msk.';

-- ---------------------------------------------------------------------------
-- 2. A flare-up pause, and a resume that understands it
-- ---------------------------------------------------------------------------
alter table public.therapy_enrolments drop constraint if exists therapy_enrolments_stop_reason_check;
alter table public.therapy_enrolments add constraint therapy_enrolments_stop_reason_check
  check (stop_reason in ('exclusion', 'crisis', 'worsening_review', 'patient_choice', 'completed', 'no_exclusion_list', 'flare_up_review'));

do $$
declare v_def text; v_new text;
begin
  v_def := pg_get_functiondef('public.resume_therapy_enrolment(uuid, text)'::regprocedure);
  if v_def not like '%flare_up_review%' then
    v_new := replace(v_def, $q$e.stop_reason <> 'worsening_review'$q$, $q$e.stop_reason not in ('worsening_review', 'flare_up_review')$q$);
    if v_new = v_def then raise exception 'S96: resume_therapy_enrolment marker not found (definition drifted)'; end if;
    execute v_new;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 3. Ratings, flare-ups and step-down periods
-- ---------------------------------------------------------------------------
create table public.therapy_msk_events (
  id              uuid primary key default gen_random_uuid(),
  organisation_id uuid not null references public.organisations (id),
  patient_id      uuid not null references public.profiles (id) on delete restrict,
  enrolment_id    uuid not null references public.therapy_enrolments (id) on delete restrict,
  kind            text not null check (kind in ('difficulty', 'flare_up', 'step_down')),
  -- difficulty: the session (week), the exercise key and a 1 to 5 rating (the range in force is therapy_programme_config.msk; this check is only a wide bound)
  ordinal         integer check (ordinal is null or ordinal >= 1),
  exercise_key    text check (exercise_key is null or exercise_key ~ '^[a-z][a-z0-9_]*$'),
  rating          smallint check (rating is null or rating between 1 and 10),
  -- flare_up: pain now 0 to 10 (optional) and what the re-check decided
  pain_now        smallint check (pain_now is null or pain_now between 0 and 10),
  outcome         text check (outcome is null or outcome in ('stopped', 'step_down')),
  -- step_down: the last day of the lighter plan, inclusive
  step_down_until date,
  event_date      date not null default ((now() at time zone 'Africa/Lagos')::date),
  is_test         boolean not null default false,
  created_at      timestamptz not null default now(),
  constraint therapy_msk_events_shape check (
       (kind = 'difficulty' and ordinal is not null and exercise_key is not null and rating is not null and outcome is null and step_down_until is null)
    or (kind = 'flare_up' and outcome is not null and rating is null and exercise_key is null and step_down_until is null)
    or (kind = 'step_down' and step_down_until is not null and rating is null and exercise_key is null))
);
-- one rating per exercise per session per day: a second one the same day replaces the first
create unique index therapy_msk_events_one_rating_per_day on public.therapy_msk_events (enrolment_id, ordinal, exercise_key, event_date) where kind = 'difficulty';
create index therapy_msk_events_enrolment_idx on public.therapy_msk_events (enrolment_id, kind, created_at desc);
comment on table public.therapy_msk_events is 'S96: difficulty ratings, flare-up reports and step-down periods for the pain programmes. Per-patient, own read only (INV-12); written only by the MSK functions; never readable through the organisation-wide staff function.';

alter table public.therapy_msk_events enable row level security;
revoke all on public.therapy_msk_events from public, anon, authenticated;
grant select on public.therapy_msk_events to authenticated;
grant all on public.therapy_msk_events to service_role;
create policy therapy_msk_events_own_read on public.therapy_msk_events for select to authenticated using (patient_id = (select auth.uid()));

-- the S39d data registry: same default classification as the S63 patient tables, awaiting the CMO and DPO review
insert into public.data_registry (table_name, patient_expr, retention_class, end_of_retention, in_export, notes)
select t.table_name, 'patient_id', private.retention_class_for(t.table_name),
       case when private.retention_class_for(t.table_name) = 'operational' then 'delete' else 'review' end,
       private.retention_class_for(t.table_name) <> 'audit',
       'Registered with the default S39d classification when S96 was added; awaiting review.'
  from unnest(array['therapy_msk_events']) as t(table_name)
 where to_regclass('public.' || t.table_name) is not null
on conflict (table_name) do nothing;

-- ---------------------------------------------------------------------------
-- 4. Functions
-- ---------------------------------------------------------------------------
-- Opens a pain-programme session. The activity safety gate is asked FIRST (a red triage event in the last 48 hours means rest: no session opens
-- and nothing is counted; an amber one means gentle exercises only). The gate can only make activity gentler, so an error asking it is treated as
-- "gentle only", never as allow. The gate's reason is deliberately not returned (it could name a pregnancy or a condition).
create or replace function public.start_msk_session(p_enrolment uuid, p_ordinal integer, p_recheck jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  e public.therapy_enrolments%rowtype;
  p public.therapy_programmes%rowtype;
  v_gate jsonb;
  v_res jsonb;
  v_ex jsonb;
  v_until date;
  v_today date := (now() at time zone 'Africa/Lagos')::date;
  v_days integer;
  v_cfg jsonb := private.therapy_config();
begin
  if v_uid is null then raise exception 'not signed in' using errcode = '42501'; end if;
  select * into e from public.therapy_enrolments where id = p_enrolment and patient_id = v_uid;
  if not found then raise exception 'not found' using errcode = '42501'; end if;
  select * into p from public.therapy_programmes where id = e.programme_id;
  if p.code not in ('pain_back', 'pain_neck', 'pain_knee', 'pain_hip') then raise exception 'not a pain programme' using errcode = '22023'; end if;
  if v_cfg is null then raise exception 'programmes are not configured' using errcode = '55000'; end if;

  begin
    v_gate := private.activity_gate_for(v_uid, true, now());
  exception when others then
    v_gate := null;
  end;
  if v_gate is null or v_gate ->> 'decision' not in ('allow', 'restrict', 'rest') then
    v_gate := jsonb_build_object('decision', 'restrict', 'max_intensity', 'gentle');
  end if;
  v_gate := jsonb_build_object('decision', v_gate ->> 'decision', 'max_intensity', v_gate ->> 'max_intensity');
  if v_gate ->> 'decision' = 'rest' then
    return jsonb_build_object('status', 'activity_rest', 'activity_gate', v_gate);
  end if;

  -- the S63 start, unchanged: guard, re-check of the entry screen (fail closed), approved-content rule, progress row
  v_res := public.start_therapy_session(p_enrolment, p_ordinal, p_recheck);
  if v_res ->> 'status' <> 'ok' then return v_res; end if;

  select s.exercises into v_ex from public.therapy_programme_sessions s
   where s.programme_id = e.programme_id and s.version = e.programme_version and s.ordinal = p_ordinal;
  select max(m.step_down_until) into v_until from public.therapy_msk_events m where m.enrolment_id = e.id and m.kind = 'step_down';
  select count(distinct m.event_date) into v_days from public.therapy_msk_events m
   where m.enrolment_id = e.id and m.kind = 'difficulty' and m.ordinal = p_ordinal;

  return v_res || jsonb_build_object(
    'exercises', coalesce(v_ex, '[]'::jsonb),
    'activity_gate', v_gate,
    'step_down', case when v_until is not null and v_until >= v_today then jsonb_build_object('until', v_until) else null end,
    'days_done', v_days,
    'days_needed', (v_cfg -> 'msk' ->> 'min_days_to_complete')::integer);
end $$;
revoke all on function public.start_msk_session(uuid, integer, jsonb) from public, anon;
grant execute on function public.start_msk_session(uuid, integer, jsonb) to authenticated;

-- Difficulty after an exercise, 1 (very easy) to 5 (too hard). Returns whether the easier version should be offered (the last N ratings all "too hard").
create or replace function public.record_msk_exercise_rating(p_enrolment uuid, p_ordinal integer, p_exercise_key text, p_rating integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  e public.therapy_enrolments%rowtype;
  p public.therapy_programmes%rowtype;
  v_cfg jsonb := private.therapy_config();
  v_total integer;
  v_n integer;
  v_hard integer;
  v_offer boolean := false;
begin
  if v_uid is null then raise exception 'not signed in' using errcode = '42501'; end if;
  select * into e from public.therapy_enrolments where id = p_enrolment and patient_id = v_uid;
  if not found then raise exception 'not found' using errcode = '42501'; end if;
  select * into p from public.therapy_programmes where id = e.programme_id;
  if p.code not in ('pain_back', 'pain_neck', 'pain_knee', 'pain_hip') then raise exception 'not a pain programme' using errcode = '22023'; end if;
  if v_cfg is null then raise exception 'programmes are not configured' using errcode = '55000'; end if;
  if e.state <> 'active' then return jsonb_build_object('status', 'not_active', 'state', e.state); end if;
  if p_rating is null or p_rating < (v_cfg -> 'msk' ->> 'difficulty_min')::integer or p_rating > (v_cfg -> 'msk' ->> 'difficulty_max')::integer then
    raise exception 'that rating is out of range' using errcode = '22023';
  end if;
  -- the session must have been started, and the exercise must be one of its exercises
  if not exists (select 1 from public.therapy_session_progress sp where sp.enrolment_id = e.id and sp.ordinal = p_ordinal) then
    raise exception 'that session was not started' using errcode = '22023';
  end if;
  if not exists (select 1 from public.therapy_programme_sessions s, jsonb_array_elements(coalesce(s.exercises, '[]'::jsonb)) x
                  where s.programme_id = e.programme_id and s.version = e.programme_version and s.ordinal = p_ordinal and x ->> 'key' = p_exercise_key) then
    raise exception 'that exercise is not in this session' using errcode = '22023';
  end if;
  insert into public.therapy_msk_events (organisation_id, patient_id, enrolment_id, kind, ordinal, exercise_key, rating, is_test)
  values (e.organisation_id, e.patient_id, e.id, 'difficulty', p_ordinal, p_exercise_key, p_rating, e.is_test)
  on conflict (enrolment_id, ordinal, exercise_key, event_date) where kind = 'difficulty' do update set rating = excluded.rating, created_at = now();

  v_n := (v_cfg -> 'msk' ->> 'too_hard_in_a_row')::integer;
  v_hard := (v_cfg -> 'msk' ->> 'too_hard_rating')::integer;
  select count(*) filter (where r.rating >= v_hard) = v_n into v_offer
    from (select m.rating from public.therapy_msk_events m
           where m.enrolment_id = e.id and m.kind = 'difficulty' and m.exercise_key = p_exercise_key
           order by m.created_at desc limit v_n) r;
  select count(distinct m.event_date) into v_total from public.therapy_msk_events m where m.enrolment_id = e.id and m.kind = 'difficulty' and m.ordinal = p_ordinal;
  return jsonb_build_object('status', 'ok', 'offer_easier', coalesce(v_offer, false), 'days_done', v_total);
end $$;
revoke all on function public.record_msk_exercise_rating(uuid, integer, text, integer) from public, anon;
grant execute on function public.record_msk_exercise_rating(uuid, integer, text, integer) to authenticated;

-- The completion gate: a week finishes only after enough different days have a difficulty rating. An already finished week is passed straight on
-- (the S63 answer is "already saved"). Checkpoint scores and the worsening check are the S63 function's, unchanged.
create or replace function public.complete_msk_session(p_enrolment uuid, p_ordinal integer, p_scores jsonb default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  e public.therapy_enrolments%rowtype;
  p public.therapy_programmes%rowtype;
  v_cfg jsonb := private.therapy_config();
  v_days integer;
  v_need integer;
begin
  if v_uid is null then raise exception 'not signed in' using errcode = '42501'; end if;
  select * into e from public.therapy_enrolments where id = p_enrolment and patient_id = v_uid;
  if not found then raise exception 'not found' using errcode = '42501'; end if;
  select * into p from public.therapy_programmes where id = e.programme_id;
  if p.code not in ('pain_back', 'pain_neck', 'pain_knee', 'pain_hip') then raise exception 'not a pain programme' using errcode = '22023'; end if;
  if v_cfg is null then raise exception 'programmes are not configured' using errcode = '55000'; end if;
  if e.state = 'active' and not exists (select 1 from public.therapy_session_progress sp where sp.enrolment_id = e.id and sp.ordinal = p_ordinal and sp.completed_at is not null) then
    v_need := (v_cfg -> 'msk' ->> 'min_days_to_complete')::integer;
    select count(distinct m.event_date) into v_days from public.therapy_msk_events m where m.enrolment_id = e.id and m.kind = 'difficulty' and m.ordinal = p_ordinal;
    if v_days < v_need then
      return jsonb_build_object('status', 'not_enough_days', 'days_done', v_days, 'days_needed', v_need);
    end if;
  end if;
  return public.complete_therapy_session(p_enrolment, p_ordinal, p_scores);
end $$;
revoke all on function public.complete_msk_session(uuid, integer, jsonb) from public, anon;
grant execute on function public.complete_msk_session(uuid, integer, jsonb) to authenticated;

-- "My pain got worse". Re-runs the deterministic red-flag screen (latest list, fail closed) on the answers given now.
--   positive, crisis route   : the plan is stopped, the S63 crisis path runs (class 1 task, urgent event, on-call page).
--   positive, any other route: the plan is PAUSED (flare_up_review), a clinical_tasks row is raised (never a notification only), a tied
--                              clinician can resume it (resume_therapy_enrolment).
--   clear                    : a step-down is recorded for the configured number of days (today counts as day one).
-- A list with no rules (cannot happen once the lists are seeded) is treated as a same-day clinician route, never as clear.
create or replace function public.report_msk_flare_up(p_enrolment uuid, p_recheck jsonb, p_pain_now integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  e public.therapy_enrolments%rowtype;
  p public.therapy_programmes%rowtype;
  v_cfg jsonb := private.therapy_config();
  v_screen jsonb;
  v_routed jsonb;
  v_until date;
  v_today date := (now() at time zone 'Africa/Lagos')::date;
begin
  if v_uid is null then raise exception 'not signed in' using errcode = '42501'; end if;
  select * into e from public.therapy_enrolments where id = p_enrolment and patient_id = v_uid;
  if not found then raise exception 'not found' using errcode = '42501'; end if;
  select * into p from public.therapy_programmes where id = e.programme_id;
  if p.code not in ('pain_back', 'pain_neck', 'pain_knee', 'pain_hip') then raise exception 'not a pain programme' using errcode = '22023'; end if;
  if v_cfg is null then raise exception 'programmes are not configured' using errcode = '55000'; end if;
  if p_pain_now is not null and (p_pain_now < 0 or p_pain_now > 10) then raise exception 'pain must be 0 to 10' using errcode = '22023'; end if;
  if e.state <> 'active' then return jsonb_build_object('status', 'not_active', 'state', e.state); end if;

  v_screen := private.therapy_evaluate_screen(p.code, p_recheck);
  if not (v_screen ->> 'passed')::boolean then
    if v_screen ->> 'route' is null then v_screen := v_screen || jsonb_build_object('route', 'same_day_clinician'); end if;
    insert into public.therapy_msk_events (organisation_id, patient_id, enrolment_id, kind, pain_now, outcome, is_test)
    values (e.organisation_id, e.patient_id, e.id, 'flare_up', p_pain_now, 'stopped', e.is_test);
    if v_screen ->> 'route' = 'crisis' then
      v_routed := private.therapy_stop_enrolment(e.id, v_screen);
    else
      update public.therapy_enrolments
         set state = 'paused', stop_reason = 'flare_up_review',
             exclusion_result = jsonb_build_object('stops', coalesce(v_screen -> 'stops', '[]'::jsonb), 'list_version', v_screen -> 'list_version')
       where id = e.id and state = 'active';
      v_routed := private.therapy_route_stop(e.id, v_screen);
    end if;
    return jsonb_build_object('status', 'stopped', 'route', v_screen ->> 'route', 'task_failed', coalesce((v_routed ->> 'task_failed')::boolean, false));
  end if;

  v_until := v_today + ((v_cfg -> 'msk' ->> 'step_down_days')::integer - 1);
  insert into public.therapy_msk_events (organisation_id, patient_id, enrolment_id, kind, pain_now, outcome, is_test)
  values (e.organisation_id, e.patient_id, e.id, 'flare_up', p_pain_now, 'step_down', e.is_test);
  insert into public.therapy_msk_events (organisation_id, patient_id, enrolment_id, kind, step_down_until, is_test)
  values (e.organisation_id, e.patient_id, e.id, 'step_down', v_until, e.is_test);
  return jsonb_build_object('status', 'step_down', 'until', v_until);
end $$;
revoke all on function public.report_msk_flare_up(uuid, jsonb, integer) from public, anon;
grant execute on function public.report_msk_flare_up(uuid, jsonb, integer) to authenticated;

-- ---------------------------------------------------------------------------
-- 5. Seeds (all DRAFT)
-- ---------------------------------------------------------------------------
-- msk-content-v1-begin (packages/shared/src/therapy-content/msk-drafts.ts mirrors it, a test fails on drift)
update public.therapy_programmes p
   set status = 'draft', title = c ->> 'title', summary = c ->> 'summary'
  from jsonb_array_elements($json$[{"code":"pain_back","title":"Back pain programme","summary":"Eight weeks of gentle, guided movement and plain advice for back pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: keep moving, gently","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Back pain is very common, and it is rarely a sign of serious damage. Staying active usually helps more than resting in bed. Each day this week, do the short set below and take a walk. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life, so we can see how you are getting on. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"knee_rock","name":"Knee rolls","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat on the floor.","Keep your shoulders on the floor.","Let both knees roll slowly to one side, only as far as is comfortable.","Bring them back to the middle, then roll to the other side."],"dose":"8 slow rolls to each side, once a day.","easier":"Roll a smaller way, or do 4 to each side.","harder":"Do 12 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and feet flat. Arrows show the knees rocking gently from side to side."},{"key":"pelvic_tilt","name":"Pelvic tilt","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat.","Breathe out, and gently press the small of your back towards the floor.","Hold for a count of 3, then let go slowly.","Keep breathing normally the whole time."],"dose":"8 tilts, holding each for 3 seconds, once a day.","easier":"Hold for 1 or 2 seconds, or do 4 tilts.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent. An arrow shows the lower back pressing gently down towards the floor."}]},{"ordinal":2,"title":"Week 2: loosening the back","kind":"exercise","body":"This week we add a gentle back arch and round. Move slowly and only as far as is comfortable. Keep walking a little each day. Many people find the back feels looser after a few days. Some do not, and that is useful to know. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"cat_camel","name":"Back arch and round","intensity":"gentle","steps":["Get on your hands and knees, with your hands under your shoulders and your knees under your hips.","Slowly round your back up towards the ceiling and let your head hang gently.","Then slowly let your back sag down a little and look forward.","Move only as far as feels comfortable."],"dose":"8 slow rounds and sags, once a day.","easier":"Make the movement smaller, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees. One arrow shows the back arching up, another shows it sagging gently down."},{"key":"pelvic_tilt","name":"Pelvic tilt","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat.","Breathe out, and gently press the small of your back towards the floor.","Hold for a count of 3, then let go slowly.","Keep breathing normally the whole time."],"dose":"8 tilts, holding each for 3 seconds, once a day.","easier":"Hold for 1 or 2 seconds, or do 4 tilts.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent. An arrow shows the lower back pressing gently down towards the floor."}]},{"ordinal":3,"title":"Week 3: waking up the muscles","kind":"exercise","body":"Strong hip and back muscles help carry your weight. This week we add the bridge. Squeeze your buttocks as you lift, and breathe normally. Keep your walking going. Try to do your set on at least three or four days. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"cat_camel","name":"Back arch and round","intensity":"gentle","steps":["Get on your hands and knees, with your hands under your shoulders and your knees under your hips.","Slowly round your back up towards the ceiling and let your head hang gently.","Then slowly let your back sag down a little and look forward.","Move only as far as feels comfortable."],"dose":"8 slow rounds and sags, once a day.","easier":"Make the movement smaller, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees. One arrow shows the back arching up, another shows it sagging gently down."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. Sitting and standing up from a chair is something you do all day, so we practise it with care. Keep your back straight and use your legs. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"This week the bridge, the arm and leg reach, and sit to stand make up your set. Keep your back still during the reach. If it feels too hard, use the easier version listed under the exercise. There is no prize for going faster. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":6,"title":"Week 6: everyday movements","kind":"exercise","body":"Think about the movements you want to do more easily, such as bending to pick something up or getting out of bed. Bend your hips and knees, keep the load close, and breathe out as you lift. Keep your walk going and add a little time if it feels comfortable. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":7,"title":"Week 7: staying on track","kind":"exercise","body":"Notice what helps you keep going. A set time, a reminder on your phone, or a walking partner can all help. If you miss a day, start again the next day. There is nothing to catch up. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Either way, keep moving most days. If your back pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]}]},{"code":"pain_neck","title":"Neck pain programme","summary":"Eight weeks of gentle neck and shoulder movement and plain advice for neck pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: gentle movement","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Neck pain is common and often settles. Gentle movement and regular breaks from one position usually help more than keeping still. Try to change position at least once an hour. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"neck_turn","name":"Neck turns","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Slowly turn your head to one side, as far as is comfortable.","Hold for a count of 2, then come back to the middle.","Turn to the other side."],"dose":"6 turns to each side, twice a day.","easier":"Turn a smaller way, or do 3 to each side.","harder":"Do 10 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders. Arrows point left and right to show turning the head gently to each side."},{"key":"shoulder_roll","name":"Shoulder rolls","intensity":"gentle","steps":["Sit or stand tall with your arms relaxed.","Lift your shoulders up towards your ears.","Roll them back and down in a slow circle.","Let your arms hang loose at the end."],"dose":"10 slow rolls, a few times a day, for example after every hour of sitting.","easier":"Do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the shoulders. Arrows show the shoulders lifting up and rolling back and down."}]},{"ordinal":2,"title":"Week 2: easing the stiffness","kind":"exercise","body":"This week we add a gentle side tilt. Move slowly and stop at the first gentle stretch. Never push into pain. Keep up your shoulder rolls whenever you have been sitting for a while. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"neck_turn","name":"Neck turns","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Slowly turn your head to one side, as far as is comfortable.","Hold for a count of 2, then come back to the middle.","Turn to the other side."],"dose":"6 turns to each side, twice a day.","easier":"Turn a smaller way, or do 3 to each side.","harder":"Do 10 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders. Arrows point left and right to show turning the head gently to each side."},{"key":"neck_side_tilt","name":"Gentle side tilt","intensity":"gentle","steps":["Sit or stand tall with your shoulders relaxed.","Slowly tilt your head so your ear moves towards your shoulder. Do not lift the shoulder.","Hold for a count of 5 when you feel a gentle stretch.","Come back to the middle, then tilt to the other side."],"dose":"3 tilts to each side, holding each for 5 seconds, twice a day.","easier":"Tilt a smaller way.","harder":"Hold for 10 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders with the head tilted a little to one side and an arrow showing the ear moving towards the shoulder."}]},{"ordinal":3,"title":"Week 3: shoulders and upper back","kind":"exercise","body":"The muscles between your shoulder blades help hold your head and neck in a comfortable place. This week we add the shoulder blade squeeze. Keep your shoulders low and your neck long. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"shoulder_roll","name":"Shoulder rolls","intensity":"gentle","steps":["Sit or stand tall with your arms relaxed.","Lift your shoulders up towards your ears.","Roll them back and down in a slow circle.","Let your arms hang loose at the end."],"dose":"10 slow rolls, a few times a day, for example after every hour of sitting.","easier":"Do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the shoulders. Arrows show the shoulders lifting up and rolling back and down."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. Think about how you sit or sleep, and whether a small change, such as raising your screen, would help. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"neck_turn","name":"Neck turns","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Slowly turn your head to one side, as far as is comfortable.","Hold for a count of 2, then come back to the middle.","Turn to the other side."],"dose":"6 turns to each side, twice a day.","easier":"Turn a smaller way, or do 3 to each side.","harder":"Do 10 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders. Arrows point left and right to show turning the head gently to each side."},{"key":"neck_side_tilt","name":"Gentle side tilt","intensity":"gentle","steps":["Sit or stand tall with your shoulders relaxed.","Slowly tilt your head so your ear moves towards your shoulder. Do not lift the shoulder.","Hold for a count of 5 when you feel a gentle stretch.","Come back to the middle, then tilt to the other side."],"dose":"3 tilts to each side, holding each for 5 seconds, twice a day.","easier":"Tilt a smaller way.","harder":"Hold for 10 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders with the head tilted a little to one side and an arrow showing the ear moving towards the shoulder."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"This week we add the gentle head press. Your head does not move. You are just waking up the muscles that support it. Use about a quarter of your strength and keep breathing. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."},{"key":"neck_press","name":"Gentle head press","intensity":"gentle","steps":["Sit tall and place your palm on your forehead.","Gently press your head into your hand. Your head should not move.","Use about a quarter of your strength. Hold for a count of 5 and keep breathing.","Relax. Then try with your hand on the side of your head, one side at a time."],"dose":"4 presses in each direction (front, left, right), holding each for 5 seconds, once a day.","easier":"Press more softly, or do 2.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with a hand on their forehead. An arrow shows the head pressing gently against the hand without moving."}]},{"ordinal":6,"title":"Week 6: whole-body movement","kind":"exercise","body":"A walk helps your neck too, because it keeps your whole body moving. Walk at an easy pace and let your arms swing. Keep your head level and your shoulders relaxed. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."},{"key":"neck_press","name":"Gentle head press","intensity":"gentle","steps":["Sit tall and place your palm on your forehead.","Gently press your head into your hand. Your head should not move.","Use about a quarter of your strength. Hold for a count of 5 and keep breathing.","Relax. Then try with your hand on the side of your head, one side at a time."],"dose":"4 presses in each direction (front, left, right), holding each for 5 seconds, once a day.","easier":"Press more softly, or do 2.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with a hand on their forehead. An arrow shows the head pressing gently against the hand without moving."}]},{"ordinal":7,"title":"Week 7: staying on track","kind":"exercise","body":"Notice what helps you keep going. A set time, a reminder on your phone, or doing a set after a meal can all help. If you miss a day, start again the next day. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Keep moving your neck and shoulders through the day. If your neck pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"neck_press","name":"Gentle head press","intensity":"gentle","steps":["Sit tall and place your palm on your forehead.","Gently press your head into your hand. Your head should not move.","Use about a quarter of your strength. Hold for a count of 5 and keep breathing.","Relax. Then try with your hand on the side of your head, one side at a time."],"dose":"4 presses in each direction (front, left, right), holding each for 5 seconds, once a day.","easier":"Press more softly, or do 2.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with a hand on their forehead. An arrow shows the head pressing gently against the hand without moving."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]}]},{"code":"pain_knee","title":"Knee pain programme","summary":"Eight weeks of gentle leg strengthening and plain advice for knee pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: starting gently","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Knees like to move, and strong thigh muscles take some of the load off the joint. Exercise is one of the most helpful things for sore knees, including knees with arthritis. Start gently. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"heel_slide","name":"Heel slides","intensity":"gentle","steps":["Lie on your back with your legs straight.","Slowly slide the heel of your sore leg towards your buttock, bending the knee.","Go only as far as is comfortable, then slide it straight again.","Keep the movement slow and smooth."],"dose":"10 slides, once or twice a day.","easier":"Slide a shorter way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back. One leg is straight, the other knee is bent, and an arrow shows the heel sliding away along the floor."},{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."}]},{"ordinal":2,"title":"Week 2: waking up the thigh","kind":"exercise","body":"This week we add the straight leg raise. Tighten the thigh first so the knee is straight, then lift. Keep your good knee bent so your back stays comfortable. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"heel_slide","name":"Heel slides","intensity":"gentle","steps":["Lie on your back with your legs straight.","Slowly slide the heel of your sore leg towards your buttock, bending the knee.","Go only as far as is comfortable, then slide it straight again.","Keep the movement slow and smooth."],"dose":"10 slides, once or twice a day.","easier":"Slide a shorter way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back. One leg is straight, the other knee is bent, and an arrow shows the heel sliding away along the floor."},{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."},{"key":"straight_leg_raise","name":"Straight leg raise","intensity":"gentle","steps":["Lie on your back. Bend the knee of your good leg with the foot flat.","Tighten the thigh of your sore leg so the knee is straight.","Lift the straight leg to the height of the other knee.","Hold for a count of 3, then lower slowly."],"dose":"8 lifts, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back, one knee bent with the foot flat, the other leg straight and lifted off the floor. An arrow points up."}]},{"ordinal":3,"title":"Week 3: standing up with control","kind":"exercise","body":"Sit to stand is something you do many times a day. This week we practise it on purpose. Use your hands if you need to and sit down slowly. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."},{"key":"straight_leg_raise","name":"Straight leg raise","intensity":"gentle","steps":["Lie on your back. Bend the knee of your good leg with the foot flat.","Tighten the thigh of your sore leg so the knee is straight.","Lift the straight leg to the height of the other knee.","Hold for a count of 3, then lower slowly."],"dose":"8 lifts, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back, one knee bent with the foot flat, the other leg straight and lifted off the floor. An arrow points up."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. If you carry extra weight, even a small loss can ease the load on your knees, and your care team can help if you would like support. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"straight_leg_raise","name":"Straight leg raise","intensity":"gentle","steps":["Lie on your back. Bend the knee of your good leg with the foot flat.","Tighten the thigh of your sore leg so the knee is straight.","Lift the straight leg to the height of the other knee.","Hold for a count of 3, then lower slowly."],"dose":"8 lifts, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back, one knee bent with the foot flat, the other leg straight and lifted off the floor. An arrow points up."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"This week we add the wall mini squat. Keep your back on the wall and bend only a short way. Keep your knees in line with your toes. Choose the easier version if it feels too much. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."},{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."}]},{"ordinal":6,"title":"Week 6: calf and balance","kind":"exercise","body":"Strong calves help your knee too. This week we add heel raises. Hold on to something steady. Keep walking a little more each week if it feels comfortable. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."},{"key":"calf_raise","name":"Heel raises","intensity":"moderate","steps":["Stand with your hands on a wall or a sturdy chair.","Rise up slowly onto your toes.","Hold for a count of 2, then lower your heels slowly.","Keep your weight even on both feet."],"dose":"10 raises, once a day.","easier":"Do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person standing with a hand on a wall, heels lifted off the floor, and an arrow pointing up."}]},{"ordinal":7,"title":"Week 7: steps and stairs","kind":"exercise","body":"This week we add stepping up onto a low step, which is a lot like climbing stairs. Hold a rail or a wall. Take your time. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Keep your legs moving most days, because the benefit lasts only while you keep going. If your knee pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."}]}]},{"code":"pain_hip","title":"Hip pain programme","summary":"Eight weeks of gentle hip strengthening and plain advice for hip pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: starting gently","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Hips like to move, and strong hip and thigh muscles help carry your weight. Exercise is one of the most helpful things for a sore hip, including a hip with arthritis. Start gently. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."}]},{"ordinal":2,"title":"Week 2: the buttock muscles","kind":"exercise","body":"This week we add the standing march. Hold on to something steady and keep your body upright. Move slowly. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"marching","name":"Standing march","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Lift one knee up in front, as high as is comfortable.","Lower it slowly and lift the other knee.","Keep your body upright."],"dose":"10 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person standing and lifting one knee in front, with an arrow pointing up."}]},{"ordinal":3,"title":"Week 3: strength at the side of the hip","kind":"exercise","body":"The muscles at the side of your hip keep you steady when you walk. This week we add the standing leg out to the side. Keep your toes pointing forward and do not lean. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. This week we also practise sit to stand, which you do many times a day. Use your hands if you need to. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"marching","name":"Standing march","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Lift one knee up in front, as high as is comfortable.","Lower it slowly and lift the other knee.","Keep your body upright."],"dose":"10 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person standing and lifting one knee in front, with an arrow pointing up."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"Your set this week is sit to stand, the standing leg out to the side, and the bridge. Choose the easier version of any exercise that feels too much. There is no prize for going faster. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."}]},{"ordinal":6,"title":"Week 6: steps and stairs","kind":"exercise","body":"This week we add stepping up onto a low step, which is a lot like climbing stairs. Hold a rail or a wall and take your time. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."}]},{"ordinal":7,"title":"Week 7: staying on track","kind":"exercise","body":"Notice what helps you keep going. A set time or a reminder on your phone can help. If you miss a day, start again the next day. Walk a little more each week if it feels comfortable. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."},{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Keep your hips moving most days, because the benefit lasts only while you keep going. If your hip pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."}]}]}]$json$::jsonb) c
 where p.code = c ->> 'code' and p.status = 'scaffold';

insert into public.therapy_programme_sessions (programme_id, version, ordinal, title, kind, text_body, duration_seconds, exercises)
select p.id, 1, (s ->> 'ordinal')::integer, s ->> 'title', s ->> 'kind', s ->> 'body', (s ->> 'durationSeconds')::integer, s -> 'exercises'
  from jsonb_array_elements($json$[{"code":"pain_back","title":"Back pain programme","summary":"Eight weeks of gentle, guided movement and plain advice for back pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: keep moving, gently","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Back pain is very common, and it is rarely a sign of serious damage. Staying active usually helps more than resting in bed. Each day this week, do the short set below and take a walk. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life, so we can see how you are getting on. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"knee_rock","name":"Knee rolls","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat on the floor.","Keep your shoulders on the floor.","Let both knees roll slowly to one side, only as far as is comfortable.","Bring them back to the middle, then roll to the other side."],"dose":"8 slow rolls to each side, once a day.","easier":"Roll a smaller way, or do 4 to each side.","harder":"Do 12 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and feet flat. Arrows show the knees rocking gently from side to side."},{"key":"pelvic_tilt","name":"Pelvic tilt","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat.","Breathe out, and gently press the small of your back towards the floor.","Hold for a count of 3, then let go slowly.","Keep breathing normally the whole time."],"dose":"8 tilts, holding each for 3 seconds, once a day.","easier":"Hold for 1 or 2 seconds, or do 4 tilts.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent. An arrow shows the lower back pressing gently down towards the floor."}]},{"ordinal":2,"title":"Week 2: loosening the back","kind":"exercise","body":"This week we add a gentle back arch and round. Move slowly and only as far as is comfortable. Keep walking a little each day. Many people find the back feels looser after a few days. Some do not, and that is useful to know. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"cat_camel","name":"Back arch and round","intensity":"gentle","steps":["Get on your hands and knees, with your hands under your shoulders and your knees under your hips.","Slowly round your back up towards the ceiling and let your head hang gently.","Then slowly let your back sag down a little and look forward.","Move only as far as feels comfortable."],"dose":"8 slow rounds and sags, once a day.","easier":"Make the movement smaller, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees. One arrow shows the back arching up, another shows it sagging gently down."},{"key":"pelvic_tilt","name":"Pelvic tilt","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat.","Breathe out, and gently press the small of your back towards the floor.","Hold for a count of 3, then let go slowly.","Keep breathing normally the whole time."],"dose":"8 tilts, holding each for 3 seconds, once a day.","easier":"Hold for 1 or 2 seconds, or do 4 tilts.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent. An arrow shows the lower back pressing gently down towards the floor."}]},{"ordinal":3,"title":"Week 3: waking up the muscles","kind":"exercise","body":"Strong hip and back muscles help carry your weight. This week we add the bridge. Squeeze your buttocks as you lift, and breathe normally. Keep your walking going. Try to do your set on at least three or four days. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"cat_camel","name":"Back arch and round","intensity":"gentle","steps":["Get on your hands and knees, with your hands under your shoulders and your knees under your hips.","Slowly round your back up towards the ceiling and let your head hang gently.","Then slowly let your back sag down a little and look forward.","Move only as far as feels comfortable."],"dose":"8 slow rounds and sags, once a day.","easier":"Make the movement smaller, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees. One arrow shows the back arching up, another shows it sagging gently down."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. Sitting and standing up from a chair is something you do all day, so we practise it with care. Keep your back straight and use your legs. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"This week the bridge, the arm and leg reach, and sit to stand make up your set. Keep your back still during the reach. If it feels too hard, use the easier version listed under the exercise. There is no prize for going faster. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":6,"title":"Week 6: everyday movements","kind":"exercise","body":"Think about the movements you want to do more easily, such as bending to pick something up or getting out of bed. Bend your hips and knees, keep the load close, and breathe out as you lift. Keep your walk going and add a little time if it feels comfortable. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":7,"title":"Week 7: staying on track","kind":"exercise","body":"Notice what helps you keep going. A set time, a reminder on your phone, or a walking partner can all help. If you miss a day, start again the next day. There is nothing to catch up. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Either way, keep moving most days. If your back pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice numbness around your private parts, a change in passing urine or opening your bowels, or weakness in your legs. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bird_dog","name":"Arm and leg reach","intensity":"moderate","steps":["Get on your hands and knees, with your back flat.","Slowly stretch one arm forward and the opposite leg back.","Keep your back still and your hips level. Do not let your back sag.","Hold for a count of 3, come back slowly, then change sides."],"dose":"6 reaches on each side, holding each for 3 seconds, once a day.","easier":"Lift just an arm, or just a leg, one at a time.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person on hands and knees with one arm stretched forward and the opposite leg stretched back, back kept flat."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]}]},{"code":"pain_neck","title":"Neck pain programme","summary":"Eight weeks of gentle neck and shoulder movement and plain advice for neck pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: gentle movement","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Neck pain is common and often settles. Gentle movement and regular breaks from one position usually help more than keeping still. Try to change position at least once an hour. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"neck_turn","name":"Neck turns","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Slowly turn your head to one side, as far as is comfortable.","Hold for a count of 2, then come back to the middle.","Turn to the other side."],"dose":"6 turns to each side, twice a day.","easier":"Turn a smaller way, or do 3 to each side.","harder":"Do 10 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders. Arrows point left and right to show turning the head gently to each side."},{"key":"shoulder_roll","name":"Shoulder rolls","intensity":"gentle","steps":["Sit or stand tall with your arms relaxed.","Lift your shoulders up towards your ears.","Roll them back and down in a slow circle.","Let your arms hang loose at the end."],"dose":"10 slow rolls, a few times a day, for example after every hour of sitting.","easier":"Do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the shoulders. Arrows show the shoulders lifting up and rolling back and down."}]},{"ordinal":2,"title":"Week 2: easing the stiffness","kind":"exercise","body":"This week we add a gentle side tilt. Move slowly and stop at the first gentle stretch. Never push into pain. Keep up your shoulder rolls whenever you have been sitting for a while. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"neck_turn","name":"Neck turns","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Slowly turn your head to one side, as far as is comfortable.","Hold for a count of 2, then come back to the middle.","Turn to the other side."],"dose":"6 turns to each side, twice a day.","easier":"Turn a smaller way, or do 3 to each side.","harder":"Do 10 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders. Arrows point left and right to show turning the head gently to each side."},{"key":"neck_side_tilt","name":"Gentle side tilt","intensity":"gentle","steps":["Sit or stand tall with your shoulders relaxed.","Slowly tilt your head so your ear moves towards your shoulder. Do not lift the shoulder.","Hold for a count of 5 when you feel a gentle stretch.","Come back to the middle, then tilt to the other side."],"dose":"3 tilts to each side, holding each for 5 seconds, twice a day.","easier":"Tilt a smaller way.","harder":"Hold for 10 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders with the head tilted a little to one side and an arrow showing the ear moving towards the shoulder."}]},{"ordinal":3,"title":"Week 3: shoulders and upper back","kind":"exercise","body":"The muscles between your shoulder blades help hold your head and neck in a comfortable place. This week we add the shoulder blade squeeze. Keep your shoulders low and your neck long. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"shoulder_roll","name":"Shoulder rolls","intensity":"gentle","steps":["Sit or stand tall with your arms relaxed.","Lift your shoulders up towards your ears.","Roll them back and down in a slow circle.","Let your arms hang loose at the end."],"dose":"10 slow rolls, a few times a day, for example after every hour of sitting.","easier":"Do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the shoulders. Arrows show the shoulders lifting up and rolling back and down."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. Think about how you sit or sleep, and whether a small change, such as raising your screen, would help. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"neck_turn","name":"Neck turns","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Slowly turn your head to one side, as far as is comfortable.","Hold for a count of 2, then come back to the middle.","Turn to the other side."],"dose":"6 turns to each side, twice a day.","easier":"Turn a smaller way, or do 3 to each side.","harder":"Do 10 to each side.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders. Arrows point left and right to show turning the head gently to each side."},{"key":"neck_side_tilt","name":"Gentle side tilt","intensity":"gentle","steps":["Sit or stand tall with your shoulders relaxed.","Slowly tilt your head so your ear moves towards your shoulder. Do not lift the shoulder.","Hold for a count of 5 when you feel a gentle stretch.","Come back to the middle, then tilt to the other side."],"dose":"3 tilts to each side, holding each for 5 seconds, twice a day.","easier":"Tilt a smaller way.","harder":"Hold for 10 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of the head and shoulders with the head tilted a little to one side and an arrow showing the ear moving towards the shoulder."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"This week we add the gentle head press. Your head does not move. You are just waking up the muscles that support it. Use about a quarter of your strength and keep breathing. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."},{"key":"neck_press","name":"Gentle head press","intensity":"gentle","steps":["Sit tall and place your palm on your forehead.","Gently press your head into your hand. Your head should not move.","Use about a quarter of your strength. Hold for a count of 5 and keep breathing.","Relax. Then try with your hand on the side of your head, one side at a time."],"dose":"4 presses in each direction (front, left, right), holding each for 5 seconds, once a day.","easier":"Press more softly, or do 2.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with a hand on their forehead. An arrow shows the head pressing gently against the hand without moving."}]},{"ordinal":6,"title":"Week 6: whole-body movement","kind":"exercise","body":"A walk helps your neck too, because it keeps your whole body moving. Walk at an easy pace and let your arms swing. Keep your head level and your shoulders relaxed. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."},{"key":"neck_press","name":"Gentle head press","intensity":"gentle","steps":["Sit tall and place your palm on your forehead.","Gently press your head into your hand. Your head should not move.","Use about a quarter of your strength. Hold for a count of 5 and keep breathing.","Relax. Then try with your hand on the side of your head, one side at a time."],"dose":"4 presses in each direction (front, left, right), holding each for 5 seconds, once a day.","easier":"Press more softly, or do 2.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with a hand on their forehead. An arrow shows the head pressing gently against the hand without moving."}]},{"ordinal":7,"title":"Week 7: staying on track","kind":"exercise","body":"Notice what helps you keep going. A set time, a reminder on your phone, or doing a set after a meal can all help. If you miss a day, start again the next day. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"chin_tuck","name":"Chin tuck","intensity":"gentle","steps":["Sit or stand tall and look straight ahead.","Glide your chin straight back, as if making a double chin. Keep your head level.","Hold for a count of 3.","Relax and let your head come back to the middle."],"dose":"8 tucks, holding each for 3 seconds, twice a day.","easier":"Do 4, and hold for 1 or 2 seconds.","harder":"Hold for 5 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of the head and shoulders. An arrow shows the chin gliding straight back, as if making a double chin, with the head level."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Keep moving your neck and shoulders through the day. If your neck pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you notice weakness or numbness spreading into your arms or hands, or changes in your balance. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"neck_press","name":"Gentle head press","intensity":"gentle","steps":["Sit tall and place your palm on your forehead.","Gently press your head into your hand. Your head should not move.","Use about a quarter of your strength. Hold for a count of 5 and keep breathing.","Relax. Then try with your hand on the side of your head, one side at a time."],"dose":"4 presses in each direction (front, left, right), holding each for 5 seconds, once a day.","easier":"Press more softly, or do 2.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with a hand on their forehead. An arrow shows the head pressing gently against the hand without moving."},{"key":"blade_squeeze","name":"Shoulder blade squeeze","intensity":"gentle","steps":["Sit or stand tall with your elbows bent by your sides.","Gently draw your shoulder blades back and together, as if holding a pencil between them.","Hold for a count of 5. Keep your shoulders low, not up by your ears.","Relax slowly."],"dose":"8 squeezes, holding each for 5 seconds, twice a day.","easier":"Do 4, and hold for 2 or 3 seconds.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Back view of a person with elbows bent. Arrows point in towards the spine to show the shoulder blades squeezing together."}]}]},{"code":"pain_knee","title":"Knee pain programme","summary":"Eight weeks of gentle leg strengthening and plain advice for knee pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: starting gently","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Knees like to move, and strong thigh muscles take some of the load off the joint. Exercise is one of the most helpful things for sore knees, including knees with arthritis. Start gently. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"heel_slide","name":"Heel slides","intensity":"gentle","steps":["Lie on your back with your legs straight.","Slowly slide the heel of your sore leg towards your buttock, bending the knee.","Go only as far as is comfortable, then slide it straight again.","Keep the movement slow and smooth."],"dose":"10 slides, once or twice a day.","easier":"Slide a shorter way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back. One leg is straight, the other knee is bent, and an arrow shows the heel sliding away along the floor."},{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."}]},{"ordinal":2,"title":"Week 2: waking up the thigh","kind":"exercise","body":"This week we add the straight leg raise. Tighten the thigh first so the knee is straight, then lift. Keep your good knee bent so your back stays comfortable. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"heel_slide","name":"Heel slides","intensity":"gentle","steps":["Lie on your back with your legs straight.","Slowly slide the heel of your sore leg towards your buttock, bending the knee.","Go only as far as is comfortable, then slide it straight again.","Keep the movement slow and smooth."],"dose":"10 slides, once or twice a day.","easier":"Slide a shorter way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back. One leg is straight, the other knee is bent, and an arrow shows the heel sliding away along the floor."},{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."},{"key":"straight_leg_raise","name":"Straight leg raise","intensity":"gentle","steps":["Lie on your back. Bend the knee of your good leg with the foot flat.","Tighten the thigh of your sore leg so the knee is straight.","Lift the straight leg to the height of the other knee.","Hold for a count of 3, then lower slowly."],"dose":"8 lifts, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back, one knee bent with the foot flat, the other leg straight and lifted off the floor. An arrow points up."}]},{"ordinal":3,"title":"Week 3: standing up with control","kind":"exercise","body":"Sit to stand is something you do many times a day. This week we practise it on purpose. Use your hands if you need to and sit down slowly. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."},{"key":"straight_leg_raise","name":"Straight leg raise","intensity":"gentle","steps":["Lie on your back. Bend the knee of your good leg with the foot flat.","Tighten the thigh of your sore leg so the knee is straight.","Lift the straight leg to the height of the other knee.","Hold for a count of 3, then lower slowly."],"dose":"8 lifts, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back, one knee bent with the foot flat, the other leg straight and lifted off the floor. An arrow points up."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. If you carry extra weight, even a small loss can ease the load on your knees, and your care team can help if you would like support. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"straight_leg_raise","name":"Straight leg raise","intensity":"gentle","steps":["Lie on your back. Bend the knee of your good leg with the foot flat.","Tighten the thigh of your sore leg so the knee is straight.","Lift the straight leg to the height of the other knee.","Hold for a count of 3, then lower slowly."],"dose":"8 lifts, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back, one knee bent with the foot flat, the other leg straight and lifted off the floor. An arrow points up."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"This week we add the wall mini squat. Keep your back on the wall and bend only a short way. Keep your knees in line with your toes. Choose the easier version if it feels too much. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."},{"key":"quad_set","name":"Thigh squeeze","intensity":"gentle","steps":["Lie on your back, or sit with your leg straight on a bed or the floor.","Put a small rolled towel under your knee.","Press the back of your knee down into the towel by tightening the muscle on top of your thigh.","Hold for a count of 5, then relax."],"dose":"10 squeezes, holding each for 5 seconds, once or twice a day.","easier":"Hold for 2 or 3 seconds, or do 5.","harder":"Hold for 8 seconds.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with a small rolled towel under one knee and an arrow showing the knee pressing down onto it."}]},{"ordinal":6,"title":"Week 6: calf and balance","kind":"exercise","body":"Strong calves help your knee too. This week we add heel raises. Hold on to something steady. Keep walking a little more each week if it feels comfortable. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."},{"key":"calf_raise","name":"Heel raises","intensity":"moderate","steps":["Stand with your hands on a wall or a sturdy chair.","Rise up slowly onto your toes.","Hold for a count of 2, then lower your heels slowly.","Keep your weight even on both feet."],"dose":"10 raises, once a day.","easier":"Do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person standing with a hand on a wall, heels lifted off the floor, and an arrow pointing up."}]},{"ordinal":7,"title":"Week 7: steps and stairs","kind":"exercise","body":"This week we add stepping up onto a low step, which is a lot like climbing stairs. Hold a rail or a wall. Take your time. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Keep your legs moving most days, because the benefit lasts only while you keep going. If your knee pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if your knee becomes hot and swollen, if you cannot put weight on it, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"mini_squat","name":"Wall mini squat","intensity":"moderate","steps":["Stand with your back against a wall and your feet a little way in front, hip width apart.","Slowly bend your knees a short way, as if starting to sit. Keep your back on the wall.","Hold for a count of 3, then straighten up slowly.","Keep your knees pointing the same way as your toes."],"dose":"8 mini squats, once a day.","easier":"Bend a smaller way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person with their back against a wall, knees slightly bent, and an arrow pointing down to show lowering a little way."}]}]},{"code":"pain_hip","title":"Hip pain programme","summary":"Eight weeks of gentle hip strengthening and plain advice for hip pain, with a few short exercises each day. A self-help programme, not treatment.","sessions":[{"ordinal":1,"title":"Week 1: starting gently","kind":"education","body":"Welcome. This is a self-help programme. It does not replace your care team. Hips like to move, and strong hip and thigh muscles help carry your weight. Exercise is one of the most helpful things for a sore hip, including a hip with arthritis. Start gently. A little discomfort while you exercise is normal. A mild rise in your usual pain that settles within an hour or by the next day is expected. Pain that is sharp, or that stays worse, means you should ease off. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. When you finish this week, the app asks four short questions about your pain and daily life. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."}]},{"ordinal":2,"title":"Week 2: the buttock muscles","kind":"exercise","body":"This week we add the standing march. Hold on to something steady and keep your body upright. Move slowly. After each exercise, tell the app how hard it felt, from very easy to too hard. This helps keep the plan the right size for you. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"marching","name":"Standing march","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Lift one knee up in front, as high as is comfortable.","Lower it slowly and lift the other knee.","Keep your body upright."],"dose":"10 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person standing and lifting one knee in front, with an arrow pointing up."}]},{"ordinal":3,"title":"Week 3: strength at the side of the hip","kind":"exercise","body":"The muscles at the side of your hip keep you steady when you walk. This week we add the standing leg out to the side. Keep your toes pointing forward and do not lean. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."},{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."}]},{"ordinal":4,"title":"Week 4: checking in","kind":"exercise","body":"You are halfway. When you finish this week, the app asks the four short questions again. If your pain is much worse than at the start, your care team will be told and will look at your plan with you. This week we also practise sit to stand, which you do many times a day. Use your hands if you need to. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."},{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"marching","name":"Standing march","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Lift one knee up in front, as high as is comfortable.","Lower it slowly and lift the other knee.","Keep your body upright."],"dose":"10 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person standing and lifting one knee in front, with an arrow pointing up."}]},{"ordinal":5,"title":"Week 5: building strength","kind":"exercise","body":"Your set this week is sit to stand, the standing leg out to the side, and the bridge. Choose the easier version of any exercise that feels too much. There is no prize for going faster. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."},{"key":"bridge","name":"Bridge","intensity":"gentle","steps":["Lie on your back with your knees bent and your feet flat, hip width apart.","Breathe out and squeeze your buttocks.","Lift your hips until your body makes a straight slope from your shoulders to your knees.","Hold for a count of 3, then lower slowly."],"dose":"8 bridges, holding each for 3 seconds, once a day.","easier":"Lift only a little way, or do 4.","harder":"Hold for 5 seconds, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their back with knees bent and hips lifted so the body makes a straight slope from shoulders to knees. An arrow points up at the hips."}]},{"ordinal":6,"title":"Week 6: steps and stairs","kind":"exercise","body":"This week we add stepping up onto a low step, which is a lot like climbing stairs. Hold a rail or a wall and take your time. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"hip_abduction_standing","name":"Standing leg out to the side","intensity":"gentle","steps":["Stand tall holding the back of a chair or a wall.","Slowly lift one leg out to the side, keeping your toes pointing forward.","Keep your body upright. Do not lean.","Lower slowly, then repeat. Change legs after a set."],"dose":"8 lifts on each leg, once a day.","easier":"Lift a smaller way, or do 4.","harder":"Do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Front view of a person standing and holding a chair back, with one leg moving out to the side. An arrow points outwards."}]},{"ordinal":7,"title":"Week 7: staying on track","kind":"exercise","body":"Notice what helps you keep going. A set time or a reminder on your phone can help. If you miss a day, start again the next day. Walk a little more each week if it feels comfortable. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"clamshell","name":"Clamshell","intensity":"gentle","steps":["Lie on your side with your knees bent and your feet together.","Keep your feet touching and lift your top knee, like a clam opening.","Do not roll your hips backwards.","Lower slowly."],"dose":"10 lifts on each side, once a day.","easier":"Lift a smaller way, or do 5.","harder":"Hold for 3 seconds at the top, or do 15.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person lying on their side with knees bent and feet together. An arrow shows the top knee lifting away like a clam opening."},{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."}]},{"ordinal":8,"title":"Week 8: looking back, and carrying on","kind":"education","body":"You have reached the end of the eight weeks. When you finish, answer the four short questions again and look at how they compare with week 1. Some people notice a change and some do not. Keep your hips moving most days, because the benefit lasts only while you keep going. If your hip pain is still getting in the way of your life, or is getting worse, tell your care team. They can talk with you about other support. Thank you for taking part. If your pain gets worse, use the button called My pain got worse. It asks a few safety questions and gives you a lighter plan for a few days. Tell your care team through the app if you cannot put weight on your leg, if you have pain in your groin after a fall, or if your calf becomes painful or swollen. If you feel very unwell or in danger, go to the nearest hospital now.","durationSeconds":600,"exercises":[{"key":"sit_to_stand","name":"Sit to stand","intensity":"moderate","steps":["Sit near the front of a firm chair, with your feet flat and hip width apart.","Lean forward a little and stand up. Use your hands on your knees or the chair if you need to.","Stand tall for a moment.","Sit back down slowly and with control."],"dose":"8 stands, once or twice a day.","easier":"Use a higher seat or push up with your hands, or do 4.","harder":"Do not use your hands, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person sitting on a chair with an arrow beside them pointing up to show standing up."},{"key":"step_up","name":"Step up","intensity":"moderate","steps":["Stand in front of a low, sturdy step. Hold a rail or a wall if you need to.","Step up with your sore leg first and stand tall.","Step back down slowly with the other leg.","Take your time and keep your knee in line with your toes."],"dose":"8 steps up with each leg, once a day.","easier":"Use a lower step, hold on, or do 4.","harder":"Use a slightly higher step, or do 12.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person stepping one foot up onto a low step, with an arrow pointing up."},{"key":"walk","name":"Easy walk","intensity":"gentle","steps":["Walk at a pace where you can still talk.","Stand tall and let your arms swing.","Walk on level ground, in comfortable shoes.","Take a short rest if you need one."],"dose":"10 minutes, once or twice a day. You can split it into shorter walks.","easier":"Walk for 5 minutes, or walk indoors.","harder":"Add 5 minutes.","stop_if":"Stop if you feel sharp pain, new numbness or pins and needles, or dizziness.","alt":"Side view of a person walking, with an arrow pointing forward."}]}]}]$json$::jsonb) c
  join public.therapy_programmes p on p.code = c ->> 'code'
  cross join lateral jsonb_array_elements(c -> 'sessions') s
on conflict (programme_id, version, ordinal) do nothing;
-- msk-content-v1-end

-- exclusion-lists-v2-begin (packages/shared/src/proposed-config/msk-config-data.ts mirrors it, a test fails on drift). Every list is a DRAFT.
insert into public.therapy_exclusion_list_versions (programme_code, version, status, note)
select p.code, 2, 'draft', 'DRAFT (S96, 2026-10-27), unconfirmed. Red flags for back, neck, knee and hip pain written from NICE NG59 and NG226 style lists, to be verified against the source by the CMO. Items marked unverified are local additions. The CMO edits by saving a higher version.'
  from public.therapy_programmes p where p.code in ('pain_back', 'pain_neck', 'pain_knee', 'pain_hip')
on conflict (programme_code, version) do nothing;

insert into public.therapy_exclusion_rules (programme_code, list_version, ordinal, item_code, question, kind, threshold, route, unverified)
